pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz the from address, the callee address (we will deploy a helper and pass its address),
    // and an array size and single value; the fuzzer will supply values
    function testFuzz_property(address from, uint256 v0, uint256 len) public {
        // keep len in a reasonable but wide range and non-zero to satisfy require(_tos.length > 0)
        uint256 l = bound(len, 1, 8);

        // build _tos array of helper addresses; we need an actual contract that will accept the low-level call
        // Deploy a benign Callee that always returns true for transferFrom selector
        BenignCallee helper = new BenignCallee();

        address[] memory tos = new address[](l);
        uint[] memory vals = new uint[](l);
        for (uint i = 0; i < l; i++) {
            tos[i] = address(helper);
            vals[i] = v0 + i; // fuzzed variation
        }

        // perform the call and capture the boolean result via try/catch to observe the return value
        bool ok;
        try c.transfer(from, address(helper), tos, vals) returns (bool r) {
            ok = r;
        } catch {
            ok = false;
        }

        // General rule: for any non-empty _tos, the reference implementation returns true when it does not revert.
        // The mutant that returns false will make this assertion fail for some inputs.
        assertTrue(ok);
    }
}

// Minimal benign callee that implements the transferFrom selector and returns true
contract BenignCallee {
    // match selector transferFrom(address,address,uint256)
    function transferFrom(address, address, uint256) external pure returns (bool) {
        return true;
    }

    // fallback to accept calls encoded with selector as in the original (not strictly necessary here)
    fallback() external payable {
        // do nothing
    }
}

