pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz parameters: from (actor), an array of recipient addresses, and corresponding amounts
    function testFuzz_property(address from, address[] memory tos, uint[] memory vals) public {
        // admissible domain: must provide a non-empty tos array and matching lengths
        vm.assume(tos.length > 0);
        vm.assume(tos.length == vals.length);

        // Deploy a helper that will accept calls and succeed (forwarded success)
        // This ensures the external low-level call from C to caddress returns true.
        AcceptingHelper h = new AcceptingHelper();

        // Call transfer on C and observe its return via try/catch (no revert expected)
        bool ok;
        try c.transfer(from, address(h), tos, vals) returns (bool ret) {
            // capture the returned boolean
            ok = ret;
        } catch {
            // if it reverts, mark ok = false
            ok = false;
        }

        // The correct contract C always returns true (ok == true) whenever it does not revert and tos is non-empty
        // Single assertion: this is true for the reference implementation for all admissible inputs
        assertTrue(ok);
    }
}

// Minimal helper that always returns true on calls with selector transferFrom(address,address,uint256)
contract AcceptingHelper {
    // accept any call and return true-encoded data
    fallback() external payable returns (bytes memory) {
        // return non-empty success bytes (ABI-encoded true) if caller expects data
        assembly {
            // store boolean true at memory 0x00
            mstore(0x00, 1)
            return(0x00, 0x20)
        }
    }
}

