pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz parameters: an address "from", an address actor for the callee, a dynamic array of tos and values
    function testFuzz_property(address from, address calleeAddr, address[] memory _tos, uint[] memory v) public {
        // admissible domain: require non-empty _tos (function under test requires it)
        vm.assume(_tos.length > 0);
        // lengths of v must match _tos to avoid out-of-bounds in the loop
        vm.assume(v.length == _tos.length);

        // Deploy a simple helper that will accept the low-level call and return success.
        // If calleeAddr supplied by fuzzer is a contract with code, use it; otherwise deploy a benign receiver.
        address target;
        if (calleeAddr.code.length == 0) {
            SimpleReceiver r = new SimpleReceiver();
            target = address(r);
        } else {
            // use the provided address if it already has code
            target = calleeAddr;
        }

        // Make sure the target's fallback returns true (SimpleReceiver does). No Ether needed.
        bool ok;
        try c.transfer(from, target, _tos, v) returns (bool retVal) {
            // the reference contract should return true for any non-empty _tos when all external calls succeed
            ok = retVal;
        } catch {
            // if it reverts, mark as false (shouldn't happen with SimpleReceiver)
            ok = false;
        }

        // Single assertion: the reference C satisfies that transfer(...) returns true for these admissible inputs
        assertTrue(ok);
    }
}

// Minimal benign callee that accepts the low-level call and returns true-encoded data
contract SimpleReceiver {
    // respond to any call with a successful (non-reverting) empty return
    fallback() external payable {
        // do nothing, succeed
    }
}

