pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzz parameters: a caller address (actor), an array of recipient addresses, and matching uint array
    function testFuzz_property(address actor, address[] memory _tos, uint256[] memory v) public {
        // admissible domain: non-empty _tos and matching lengths
        vm.assume(_tos.length > 0);
        vm.assume(_tos.length == v.length);
        // Deploy a callee that always succeeds for the transferFrom selector
        CalleeAlwaysSucceeds callee = new CalleeAlwaysSucceeds();

        // Ensure actor has some ETH to be able to call if needed (not strictly required here)
        vm.deal(actor, 1 ether);

        // Call transfer from actor (we don't rely on msg.sender inside C, but keep the call realistic)
        bool ok;
        vm.prank(actor);
        try c.transfer(actor, address(callee), _tos, v) returns (bool ret) {
            ok = ret;
        } catch {
            ok = false;
        }

        // The general invariant: for any non-empty _tos where the callee always succeeds on the selector,
        // the reference implementation returns true. The mutant that returns false will fail this assertion
        // for some inputs. We assert that ok is true.
        assertTrue(ok);
    }
}

// Helper callee that emulates a contract whose low-level call with the selector
// transferFrom(address,address,uint256) succeeds (returns true) — it must accept arbitrary calldata
contract CalleeAlwaysSucceeds {
    // Accept any call and return (true) encoded as bytes to simulate a successful external call
    fallback() external payable returns (bytes memory) {
        // return abi.encode(true);
        // But low-level .call expects raw returned data; encoding true as bool is fine
        bytes memory ret = abi.encode(true);
        return ret;
    }

    receive() external payable {}
}

