pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed params: from address, the callee (we will deploy a helper and still fuzz an address used as 'from'),
    // a uint[] amounts and an address[] tos. Fuzzer supplies them.
    function testFuzz_property(address from, uint[] memory v, address[] memory _tos) public {
        // domain: _tos must be non-empty as required by the contract
        vm.assume(_tos.length > 0);
        // Deploy a helper that always succeeds when called with the selector transferFrom(address,address,uint256)
        SucceedsCaller helper = new SucceedsCaller();

        // Build amounts array: if lengths mismatch, bound v to _tos length by resizing
        // If v is shorter, pad with some nonzero values; keep wide domain
        if (v.length < _tos.length) {
            uint[] memory v2 = new uint[](_tos.length);
            for (uint i = 0; i < _tos.length; i++) {
                if (i < v.length) v2[i] = v[i]; else v2[i] = uint256(1);
            }
            v = v2;
        }
        // If v is longer, truncate to match
        if (v.length > _tos.length) {
            uint[] memory v2 = new uint[](_tos.length);
            for (uint i = 0; i < _tos.length; i++) v2[i] = v[i];
            v = v2;
        }

        // Now call transfer on c, routing all external calls to the helper address (which succeeds)
        bool ok;
        try c.transfer(from, address(helper), _tos, v) {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule: for any non-empty _tos and a callee that succeeds on the selector, transfer returns (completes) and yields true.
        // We observe completion via ok (no revert) and then call again expecting a true return value by using a low-level call to read the return.
        // But per constraints we must assert a single assertTrue reading c's behavior. We'll assert that the call completed (did not revert)
        // AND returned true by invoking the function via try/catch to capture its return value. Since try above only captured revert, we need an actual call to get the return value.

        // Do a direct call via interface to capture return value using try/catch on the external call that returns (bool)
        bool ret;
        try c.transfer(from, address(helper), _tos, v) returns (bool r) {
            ret = r;
        } catch {
            // If it reverts, ret should be false for the mutant, but reference never reverts here — make ret false
            ret = false;
        }

        // The single required assertion: the reference contract always returns true for this scenario (helper always succeeds),
        // so assertTrue(ret) — the mutant returning false will cause some fuzzed inputs to fail this assertion.
        assertTrue(ret);
    }
}

// Helper contract that returns success for the transferFrom selector
contract SucceedsCaller {
    // implement a fallback that recognizes the selector and returns (bool) true encoded
    fallback() external payable returns (bytes memory) {
        // If called with the selector for transferFrom(address,address,uint256), return ABI-encoded true
        // We always return true for any calldata to simulate a successful external call
        bytes memory out = abi.encode(true);
        return out;
    }

    receive() external payable {}
}
